package com.example.data.engine

import com.example.data.config.NeuraConfig
import java.util.regex.Pattern

object NeuraIntelligenceEngine {

    sealed class FastIntentResult {
        data class ContextEnriched(val resolvedPrompt: String, val systemModeHint: String?) : FastIntentResult()
        data object StandardPassThrough : FastIntentResult()
    }

    /**
     * Evaluates whether the user's prompt needs context enrichment
     * from multi-turn history (e.g., follow-up pronouns like 'ye samjha', 'iska code').
     * All responses are generated by the real Gemini model.
     */
    fun evaluateFastIntent(
        rawPrompt: String,
        conversationHistory: List<String>
    ): FastIntentResult {
        val trimmed = rawPrompt.trim()

        // Follow-up pronoun / conversational continuity detection
        val enriched = resolveContextualFollowUp(trimmed, conversationHistory)
        if (enriched != null) {
            return FastIntentResult.ContextEnriched(enriched.first, enriched.second)
        }

        return FastIntentResult.StandardPassThrough
    }

    /**
     * Evaluates simple arithmetic expressions like "2 + 2", "50 * 4", "100 / 4"
     * and returns an immediate concise response.
     */
    private fun tryEvaluateSimpleMath(prompt: String): String? {
        val clean = prompt.replace("?", "").replace("=", "").trim()

        // Regex for simple binary operations: e.g. "2 + 2", "15 * 12", "100 / 5", "25 - 7"
        val binaryPattern = Pattern.compile("^([0-9]+(?:\\.[0-9]+)?)\\s*([+\\-*/x×÷^])\\s*([0-9]+(?:\\.[0-9]+)?)$")
        val matcher = binaryPattern.matcher(clean)

        if (matcher.matches()) {
            val left = matcher.group(1)?.toDoubleOrNull() ?: return null
            val op = matcher.group(2) ?: return null
            val right = matcher.group(3)?.toDoubleOrNull() ?: return null

            val result: Double = when (op) {
                "+", "plus" -> left + right
                "-", "minus" -> left - right
                "*", "x", "×", "times" -> left * right
                "/", "÷" -> if (right != 0.0) left / right else return "Undefined (division by zero) ⚠️"
                "^" -> Math.pow(left, right)
                else -> return null
            }

            val formatted = if (result % 1.0 == 0.0) {
                result.toLong().toString()
            } else {
                String.format("%.4f", result).trimEnd('0').trimEnd('.')
            }

            return "$formatted 😄"
        }

        // Single number inquiry or square root: e.g. "sqrt(144)" or "sqrt 144"
        val sqrtPattern = Pattern.compile("^(?:sqrt|square root of|v)\\s*\\(?([0-9]+(?:\\.[0-9]+)?)\\)?$", Pattern.CASE_INSENSITIVE)
        val sqrtMatcher = sqrtPattern.matcher(clean)
        if (sqrtMatcher.matches()) {
            val num = sqrtMatcher.group(1)?.toDoubleOrNull() ?: return null
            if (num < 0) return "Imaginary number ($num < 0)"
            val sqrtVal = Math.sqrt(num)
            val formatted = if (sqrtVal % 1.0 == 0.0) sqrtVal.toLong().toString() else String.format("%.4f", sqrtVal)
            return "$formatted 😄"
        }

        return null
    }

    private fun isDeveloperQuestion(lower: String): Boolean {
        return (lower.contains("who developed you") ||
                lower.contains("who created you") ||
                lower.contains("who made you") ||
                lower.contains("who is your developer") ||
                lower.contains("who is your creator") ||
                lower.contains("developer kaun hai") ||
                lower.contains("kisne banaya") ||
                lower.contains("who built you"))
    }

    private fun isExamPanic(lower: String): Boolean {
        return (lower.contains("kal exam hai") ||
                lower.contains("exam tomorrow") ||
                lower.contains("kuch nahi padha") ||
                lower.contains("kuch nhi padha") ||
                lower.contains("haven't studied anything") ||
                lower.contains("exam hai aur darr lag raha"))
    }

